```rust
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Shared {
    m1: Mutex<()>,
    m2: Mutex<()>,
    cv: Condvar,
    announced: Mutex<i32>,
    done: Mutex<i32>,
}

fn main() {
    let shared = Arc::new(Shared {
        m1: Mutex::new(()),
        m2: Mutex::new(()),
        cv: Condvar::new(),
        announced: Mutex::new(0),
        done: Mutex::new(0),
    });

    let s1 = Arc::clone(&shared);
    let waiter1 = thread::spawn(move || {
        let _g1 = s1.m1.lock().unwrap();
        {
            let mut a = s1.announced.lock().unwrap();
            let a2 = *a + 1;
            *a = a2;
        }
        let _g1 = s1.cv.wait(_g1).unwrap();
        {
            let mut d = s1.done.lock().unwrap();
            let d2 = *d + 1;
            *d = d2;
        }
        drop(_g1);
    });

    let s2 = Arc::clone(&shared);
    let waiter2 = thread::spawn(move || {
        let g2 = s2.m2.lock().unwrap();
        {
            let _g1 = s2.m1.lock().unwrap();
            let mut a = s2.announced.lock().unwrap();
            let a2 = *a + 1;
            *a = a2;
        }
        let g2 = s2.cv.wait(g2).unwrap();
        {
            let _g1 = s2.m1.lock().unwrap();
            let mut d = s2.done.lock().unwrap();
            let d2 = *d + 1;
            *d = d2;
        }
        drop(g2);
    });

    let s3 = Arc::clone(&shared);
    let notifier = thread::spawn(move || {
        let g1 = s3.m1.lock().unwrap();
        loop {
            let a = s3.announced.lock().unwrap();
            if *a == 2 {
                break;
            }
            drop(a);
            drop(g1);
            g1 = s3.m1.lock().unwrap();
        }
        let g2 = s3.m2.lock().unwrap();
        s3.cv.notify_all();
        drop(g2);
        drop(g1);
    });

    waiter1.join().unwrap();
    waiter2.join().unwrap();
    notifier.join().unwrap();

    let done = *shared.done.lock().unwrap();
    println!("DONE done={}", done);
}
